    int result;

    if (!sctp_assoc_id_valid(sk, id))
        return -EINVAL;

    if (sctp_assoc_has_waiting(sk, id))
        return -EBUSY;

    if (!sctp_can_peeloff(sk))
        return -EINVAL;

    result = sock_create_kern(&init_net, sk->sk_family, SOCK_STREAM, IPPROTO_SCTP, sockp);
    if (result < 0)
        return result;

    sctp_migrate_assoc(sk, *sockp, id);

