int sctp_peeloff(struct sock *sk, sctp_assoc_t id, struct socket **sockp) {
    struct sctp_association *asoc;

    if (!sk || !sockp)
        return -EINVAL;

    asoc = sctp_id2assoc(sk, id);
    if (!asoc)
        return -EINVAL;

    if (atomic_read(&asoc->ep->refcnt) > 1)
        return -EBUSY;

    *sockp = sock_alloc();
    if (!*sockp)
        return -ENOMEM;

    sock_graft(*sockp, sk->sk_sleep);

    asoc->base.sk = (*sockp)->sk;
    sctp_association_copy((*sockp)->sk, asoc);

    return 0;
}

int sctp_peeloff(struct sock *sk, sctp_assoc_t id, struct socket **sockp) {
    int ret = -EINVAL;

    if (!sctp_assoc_valid(sk, id))
        return ret;

    if (sctp_has_waiting_threads(sk, id))
        return -EBUSY;

    if (!sctp_is_peelable(sk))
        return -EOPNOTSUPP;

    ret = sctp_create_new_sock(sk, id, sockp);
    if (ret < 0)
        return ret;

    sctp_copy_properties(sk, *sockp);
    sctp_migrate_association(sk, *sockp, id);

    return 0;
}

int sctp_peeloff(struct sock *sk, sctp_assoc_t id, struct socket **sockp) {
    struct sctp_association *asoc;
    int result = -EINVAL;

    asoc = sctp_id2assoc(sk, id);
    if (!asoc)
        return -EINVAL;

    if (asoc->ep->base.type != SOCK_STREAM)
        return -EINVAL;

    if (asoc->ep->base.type != sk->sk_type)
        return -EINVAL;

    result = sock_create_kern(&init_net, asoc->ep->base.type, asoc->ep->base.type, 0, sockp);
    if (result < 0)
        return result;

    sctp_association_dup((struct sock *)(*sockp), asoc);
    sctp_migration_dup((struct sock *)(*sockp), asoc);

    return 0;
}

int sctp_peeloff(struct sock *sk, sctp_assoc_t id, struct socket **sockp) {
    struct sctp_association *asoc;
    struct socket *new_sock;
    int ret;

    asoc = sctp_id2assoc(sk, id);
    if (!asoc)
        return -EINVAL;

    if (atomic_read(&asoc->ep->refcnt) > 1)
        return -EBUSY;

    if (sctp_style(sk, UDP))
        return -EINVAL;

    ret = sock_create_kern(current->nsproxy->net_ns, PF_INET, SOCK_SEQPACKET, IPPROTO_SCTP, &new_sock);
    if (ret < 0)
        return ret;

    sctp_copy_sock(new_sock->sk, sk);
    sctp_association_move_to_new_sk(asoc, new_sock->sk);
    *sockp = new_sock;

    return 0;
}
